package com.univmar.customer.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="customer_address") public class CustomerAddress { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id",nullable=false) private Customer customer; @Column(nullable=false,length=40) private String label; @Column(nullable=false,length=160) private String line1; @Column(length=160) private String line2; @Column(length=100) private String city; @Column(length=100) private String country; @Column(length=30) private String postalCode; protected CustomerAddress(){} public CustomerAddress(Customer customer,String label,String line1,String line2,String city,String country,String postalCode){id=UUID.randomUUID();this.customer=customer;this.label=label;this.line1=line1;this.line2=line2;this.city=city;this.country=country;this.postalCode=postalCode;} public UUID getId(){return id;} public String getLabel(){return label;} public String getLine1(){return line1;} public String getLine2(){return line2;} public String getCity(){return city;} public String getCountry(){return country;} public String getPostalCode(){return postalCode;} }
